 F fixture(String tag,boolean lot,String stock)throws Exception{
  String name="G3"+tag+UUID.randomUUID().toString().substring(0,6);Trx tx=Trx.get(Trx.createTrxName("G3_master"),true);String t=tx.getTrxName();F f;boolean ok=false;
  try{
   MWarehouse w=new MWarehouse(actor,0,t);w.setAD_Org_ID(11);w.setValue(name);w.setName(name);w.setC_Location_ID(DB.getSQLValueEx(null,"SELECT min(c_location_id) FROM m_warehouse WHERE ad_client_id=11"));w.set_ValueOfColumn("EVA_TipEvidenta","CV");w.saveEx();MLocator l=new MLocator(w,"G1");l.setX("G1");l.setY("0");l.setZ("0");l.setIsDefault(true);l.saveEx();
   int attribute=0,a1=0,a2=0;if(lot){MAttributeSet a=new MAttributeSet(actor,0,t);a.setAD_Org_ID(11);a.setName(name+"Lots");a.setIsLot(true);a.setIsLotMandatory(false);a.setIsSerNo(false);a.setIsGuaranteeDate(false);a.setIsInstanceAttribute(true);a.saveEx();attribute=a.get_ID();MAttributeSetInstance x=new MAttributeSetInstance(actor,0,attribute,t);x.setAD_Org_ID(11);x.setLot(name+"L1");x.setDescription(name+"L1");x.saveEx();a1=x.get_ID();MAttributeSetInstance y=new MAttributeSetInstance(actor,0,attribute,t);y.setAD_Org_ID(11);y.setLot(name+"L2");y.setDescription(name+"L2");y.saveEx();a2=y.get_ID();}
   if(tag.equals("main"))product(name+"spare",0,t);MProduct p=product(name+"P",attribute,t);
   PO source=MTable.get(actor,"EVA_SursaSite").getPO(0,t);source.set_ValueOfColumn("AD_Org_ID",11);source.set_ValueOfColumn("EVA_Sursa",name);source.set_ValueOfColumn("EVA_GestiuniStoc",String.valueOf(w.get_ID()));source.set_ValueOfColumn("M_Warehouse_ID",w.get_ID());source.set_ValueOfColumn("EVA_StocRezerva",BigDecimal.ZERO);source.set_ValueOfColumn("EVA_Limba","en_US");for(String n:List.of("EVA_VanzariOnline","EVA_ScrierePermisa","EVA_FisaSpreSite","EVA_StocSpreSite","EVA_SursaProprie"))source.set_ValueOfColumn(n,false);source.set_ValueOfColumn("EVA_UrlApi",null);source.saveEx();
   f=new F(tag,w.get_ID(),l.get_ID(),p.get_ID(),source.get_ID(),attribute,a1,a2);tx.commit(true);ok=true;
  }finally{if(!ok)tx.rollback();tx.close();}
  check(new MProduct(actor,f.product,null).getAD_Client_ID()==11&&new MWarehouse(actor,f.warehouse,null).getAD_Client_ID()==11,"ownership");check(f.product!=f.warehouse,"distinct IDs detect arg reversal");
  if(lot){check(MAttributeSet.get(f.attribute).isInstanceAttribute(),"committed instance attribute");check(new MAttributeSetInstance(actor,f.asi1,null).getM_AttributeSet_ID()==f.attribute&&new MAttributeSetInstance(actor,f.asi2,null).getM_AttributeSet_ID()==f.attribute,"ASI membership");}
  checkpoint(f,"masterdata_committed");
  tx=Trx.get(Trx.createTrxName("G3_stock"),true);ok=false;try{if(lot){check(MStorageOnHand.add(actor,f.warehouse,f.locator,f.product,f.asi1,bd("6"),tx.getTrxName()),"lot stock1");check(MStorageOnHand.add(actor,f.warehouse,f.locator,f.product,f.asi2,bd("4"),tx.getTrxName()),"lot stock2");}else check(MStorageOnHand.add(actor,f.warehouse,f.locator,f.product,0,bd(stock),tx.getTrxName()),"stock fixture");tx.commit(true);ok=true;}finally{if(!ok)tx.rollback();tx.close();}
  System.out.println("FIXTURE_G3|"+f+"|stock="+stock+"|masterdata_committed_before_reservations");readback(f,"fixture");return f;
 }
