 void checkpoint(F f,String label)throws Exception{
  java.nio.file.Path root=java.nio.file.Path.of(System.getProperty("AdempiereHome")),req=root.resolve("g3-request.txt"),tmp=root.resolve("g3-request.tmp"),ack=root.resolve("g3-response.txt");String token=Long.toString(System.nanoTime());
  java.nio.file.Files.writeString(tmp,String.join("|",token,f.tag,label,Integer.toString(f.product),Integer.toString(f.warehouse),Integer.toString(f.source)));java.nio.file.Files.move(tmp,req,java.nio.file.StandardCopyOption.REPLACE_EXISTING);
  long deadline=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<deadline){if(java.nio.file.Files.exists(ack)&&java.nio.file.Files.readString(ack).equals(token)){System.out.println("PYTHON_READBACK_ACK|"+token+"|"+f.tag+"|"+label);return;}Thread.sleep(25);}throw new AssertionError("independent readonly oracle timeout "+label);
 }
 void readback(F f,String label)throws Exception{
  try(Connection con=DB.getConnection(true);Statement st=con.createStatement()){con.setReadOnly(true);check(con.getAutoCommit(),"readback separate autocommit");String q="SELECT pg_backend_pid(),(SELECT coalesce(json_agg(json_build_object('uuid',m_storagereservation_uu,'client',ad_client_id,'org',ad_org_id,'product',m_product_id,'warehouse',m_warehouse_id,'asi',m_attributesetinstance_id,'so',issotrx,'qty',qty,'active',isactive,'updatedby',updatedby)), '[]'::json)::text FROM m_storagereservation WHERE m_product_id="+f.product+" AND m_warehouse_id="+f.warehouse+"),(SELECT coalesce(sum(qtyonhand),0) FROM m_storageonhand WHERE m_product_id="+f.product+"),(SELECT count(*) FROM fact_acct WHERE m_product_id="+f.product+")";try(ResultSet r=st.executeQuery(q)){r.next();System.out.println("INDEPENDENT_CONNECTION_READBACK|"+f.tag+"|"+label+"|pid="+r.getInt(1)+"|reservations="+r.getString(2)+"|onhand="+r.getBigDecimal(3)+"|fixtureFacts="+r.getInt(4));check(r.getInt(4)==0,"no fixture facts");}}
  checkpoint(f,label);
 }
