  F lot=fixture("lot",true,"10");committedAdd(lot,lot.asi1,"1",true);committedAdd(lot,lot.asi2,"1",true);committedAdd(lot,lot.asi1,"5",false);observe(lot,"G3-F04-ASIall","2","5","8","7","3",3,null);eq(MStorageReservation.getQty(lot.product,lot.warehouse,lot.asi1,true,null),"1","lot1SO");eq(MStorageReservation.getQty(lot.product,lot.warehouse,lot.asi2,true,null),"1","lot2SO");eq(MStorageReservation.getQtyAvailable(lot.warehouse,lot.product,lot.asi1,null),"5","lot1Available");eq(MStorageReservation.getQtyAvailable(lot.warehouse,lot.product,lot.asi2,null),"3","lot2Available");System.out.println("CASE_G3|G3-F04-ASIspecific|ASI1="+lot.asi1+"|ASI2="+lot.asi2+"|SO1=1|SO2=1|available1=5|available2=3|ASI0=aggregate");
